      "number": 14,
      "arFull": "وَلَقَدْ اَرْسَلْنَا نُوْحًا اِلٰی قَوْمِهٖ فَلَبِثَ فِیْهِمْ اَلْفَ سَنَةٍ اِلَّا خَمْسِیْنَ عَامًا ؕ فَاَخَذَهُمُ الطُّوْفَانُ وَهُمْ ظٰلِمُوْنَ ۟",
      "ur": "اور ہم نے نوح (علیہ السلام) کو ان کی قوم کی طرف بھیجا وه ان میں ساڑھے نو سو سال تک رہے[1] ، پھر تو انہیں طوفان نے دھر پکڑا اور وه تھے بھی ﻇالم.",
      "en": "And We certainly sent Noah to his people, and he remained among them a thousand years minus fifty years, and the flood seized them while they were wrongdoers.",
      "footnotesUr": "[1] قرآن کے الفاظ سے معلوم ہوتا ہے کہ یہ ان کی دعوت وتبلیغ کی عمر ہے۔ ان کی پوری عمر کتنی تھی؟ اس کی صراحت نہیں کی گئی۔ بعض کہتے ہیں چالیس سال نبوت سے قبل اور ساٹھ سال طوفان کے بعد، اس میں شامل کر لیے جائیں۔ اور بھی کئی اقوال ہیں، وَاللهُ أَعْلَمُ بِالصَّوَابِ۔",
      "footnotesEn": null,
