      "number": 66,
      "arFull": "لِیَكْفُرُوْا بِمَاۤ اٰتَیْنٰهُمْ ۙۚ وَلِیَتَمَتَّعُوْا ۥ فَسَوْفَ یَعْلَمُوْنَ ۟",
      "ur": "تاکہ ہماری دی ہوئی نعمتوں سے مکرتے رہیں اور برتتے رہیں[1] ۔ ابھی ابھی پتہ چل جائے گا.",
      "en": "So that they will deny what We have granted them, and they will enjoy themselves. But they are going to know.[1134]",
      "footnotesUr": "[1] یہ لام کئی ہے جو علت کے لئے ہے۔ یعنی نجات کے بعد ان کا شرک کرنا، اس لئے ہے کہ وہ کفران نعمت کریں اور دنیا کی لذتوں سے متمتع ہوتے رہیں۔ کیونکہ اگر وہ یہ ناشکری نہ کرتے تو اخلاص پر قائم رہتے اور صرف الہٰ واحد کو ہی ہمیشہ پکارتے۔ بعض کے نزدیک یہ لام عاقبت کے لئے ہے، یعنی گو ان کا مقصد کفر کرنا نہیں ہے لیکن دوبارہ شرک کے ارتکاب کا نتیجہ بہرحال کفر ہی ہے۔",
      "footnotesEn": "[1134] Grammatically, the verse may also be read as a threat, i.e., \"So let them deny what We have granted them and let them enjoy themselves, for they are going to know.\"",
